codeExamples.code:
-- Prefix: starts with 'John' (anchored, index-friendly)
SELECT name FROM users WHERE name LIKE 'John%';

-- Suffix: ends with '@gmail.com' (leading wildcard -> full scan)
SELECT email FROM users WHERE email LIKE '%@gmail.com';

-- Contains: has 'error' anywhere (leading wildcard -> full scan)
SELECT message FROM logs WHERE message LIKE '%error%';

-- Single-character wildcard: exactly three chars ending in 'at'
SELECT word FROM dictionary WHERE word LIKE '_at';

-- Fixed-length mask: a code like 'A12', 'B45' (letter + two chars)
SELECT code FROM products WHERE code LIKE '___';

-- NOT LIKE: names that do NOT start with 'John'
SELECT name FROM users WHERE name NOT LIKE 'John%';

-- Find discount codes that literally start with '50%'.
-- Without ESCAPE the % would be a wildcard.
SELECT code FROM promos
WHERE code LIKE '50\%%' ESCAPE '\';

-- Match a literal underscore: rows where sku is exactly 'A_B'
SELECT sku FROM items
WHERE sku LIKE 'A\_B' ESCAPE '\';

-- Case-insensitive match (PostgreSQL): matches 'Apple', 'APPLE', 'apple'
SELECT name FROM fruits WHERE name ILIKE 'apple%';

-- Portable case-insensitive match via LOWER (may bypass a plain index)
SELECT name FROM fruits WHERE LOWER(name) LIKE LOWER('apple%');
